import type { ChildProcess } from 'child_process';
import fs from 'fs';
import path from 'path';
import { PreviewEnvironment } from '../services/PreviewEnvironment';
import {
  resolveProjectPackageManager,
  type PreviewPackageManager,
} from '../services/ProjectPackageManager';
import { buildDevServerCommand } from '../utils/devServerCommand';
import {
  DevServerStartError,
  isDevServerStartError,
  isMissingDependencyOutput,
  type DevServerFailureReason,
} from '../utils/devServerError';
import { createLogger } from '../utils/logger';
import type { ProjectContext } from './contracts';
import type {
  ProjectEnvironment,
  WorktreeManagerLike,
} from './variant-project-runtime';
import {
  assertDevScriptExists,
  canInstallWithoutTouchingHost,
} from './variantWorkspaceFiles';
import {
  trackFreshDevServerFailed,
  trackFreshDevServerStarted,
  trackPreviewFailed,
  trackPreviewReady,
  trackPreviewStarted,
  type VariantsTelemetry,
} from './variantsTelemetry';
import { errorMessage } from '../utils/errorMessage';
import {
  failureReason,
  failureReasonCode,
  type FailureReasonCode,
} from '../utils/failureReason';
import { isPathStrictlyInsideRoot } from '../utils/pathContainment';

const log = createLogger('PreviewRuntime');
const FRESH_DEV_SERVER_HOST = '127.0.0.1';
const FRESH_DEV_SERVER_DEFAULT_PORT = 5173;
const DEV_SERVER_START_MAX_ATTEMPTS = 3;
const DEV_SERVER_MAX_AUTO_RESTARTS = 2;
const REPORTED_FAILURE_REASONS: ReadonlySet<PreviewFailure['reason']> =
  new Set(['dependency_install_failed', 'spawn_error']);

export type ResolvedDevServer = {
  cwd: string;
  cmd: string;
  args: string[];
  env: Record<string, string>;
  packageManager: PreviewPackageManager;
};

export type PreviewFailure = {
  reason:
    | DevServerFailureReason
    | 'missing_static_entry'
    | 'idle_timeout'
    | 'unknown';
  portInUse: boolean;
  detail?: string;
  reasonCode?: FailureReasonCode;
  reasonDetail?: string;
  nodeVersion?: string;
};

type VariantPreview = {
  worktreePath: string;
  port?: number;
  process?: ChildProcess;
  command?: ResolvedDevServer;
  autoRestarts: number;
  restoration?: Promise<number | undefined>;
  pendingRestart?: NodeJS.Timeout;
};

type SessionPreviewState = {
  variants: Map<string, VariantPreview>;
  failures: Map<string, PreviewFailure>;
  idleTimer?: NodeJS.Timeout;
  idleStop?: Promise<void>;
};

type PreviewRuntimeDeps = {
  worktreeManager: WorktreeManagerLike;
  resolveProjectEnvironment: (sessionId: string) => Promise<ProjectEnvironment>;
  getProjectContext: (sessionId: string) => ProjectContext;
  getDependencySignal: (sessionId: string) => AbortSignal | undefined;
  installDependencies: (
    worktreePath: string,
    options?: { workspaceRoot: string; force?: boolean; signal?: AbortSignal },
  ) => Promise<void>;
  telemetry: VariantsTelemetry;
  isSessionLive: (sessionId: string) => boolean;
  isCleanupStarted: (sessionId: string) => boolean;
  hasUiClients: () => boolean;
  changed: () => void;
  switchPreviewPort?: (port: number | null) => void;
  activeVariantServerIdleTtlMs: number;
  devServerRestartDelayMs: number;
};

export class PreviewRuntime {
  private readonly sessions = new Map<string, SessionPreviewState>();
  private readonly environment = new PreviewEnvironment();

  constructor(private readonly deps: PreviewRuntimeDeps) {}

  openSession(sessionId: string): void {
    if (this.sessions.has(sessionId)) return;
    this.sessions.set(sessionId, {
      variants: new Map(),
      failures: new Map(),
    });
  }

  registerVariant(
    sessionId: string,
    workItemId: string,
    worktreePath: string,
  ): void {
    const state = this.requireSession(sessionId);
    const current = state.variants.get(workItemId);
    if (current) {
      current.worktreePath = worktreePath;
      return;
    }
    state.variants.set(workItemId, {
      worktreePath,
      autoRestarts: 0,
    });
  }

  getPort(sessionId: string, workItemId: string): number | undefined {
    return this.sessions.get(sessionId)?.variants.get(workItemId)?.port;
  }

  getRunningVariant(
    sessionId: string,
    workItemId: string,
  ): { command: ResolvedDevServer; port: number } | undefined {
    const preview = this.sessions.get(sessionId)?.variants.get(workItemId);
    if (!preview?.command || preview.port === undefined) return undefined;
    return { command: preview.command, port: preview.port };
  }

  getFailure(
    sessionId: string,
    workItemId: string,
  ): PreviewFailure | undefined {
    return this.sessions.get(sessionId)?.failures.get(workItemId);
  }

  setFailure(
    sessionId: string,
    workItemId: string,
    failure: PreviewFailure,
  ): void {
    this.requireSession(sessionId).failures.set(workItemId, failure);
  }

  clearFailure(sessionId: string, workItemId: string): void {
    this.sessions.get(sessionId)?.failures.delete(workItemId);
  }

  touch(sessionId: string): void {
    const state = this.sessions.get(sessionId);
    if (!state || this.deps.isCleanupStarted(sessionId)) return;
    const ttl = this.deps.activeVariantServerIdleTtlMs;
    if (!Number.isFinite(ttl) || ttl <= 0) return;
    this.clearIdleTimer(state);
    state.idleTimer = setTimeout(() => {
      state.idleTimer = undefined;
      void this.stopIdleVariants(sessionId);
    }, ttl);
    state.idleTimer.unref?.();
  }

  async startVariant(args: {
    sessionId: string;
    workItemId: string;
    worktreePath: string;
    isFresh: boolean;
  }): Promise<number | undefined> {
    this.registerVariant(args.sessionId, args.workItemId, args.worktreePath);
    const preview = this.requireVariant(args.sessionId, args.workItemId);
    return this.startVariantProcess({ ...args, preview });
  }

  async restoreVariant(args: {
    sessionId: string;
    workItemId: string;
    worktreePath: string;
    isFresh: boolean;
    isSucceeded: boolean;
    retryFailed?: boolean;
  }): Promise<number | undefined> {
    this.registerVariant(args.sessionId, args.workItemId, args.worktreePath);
    const state = this.requireSession(args.sessionId);
    const preview = this.requireVariant(args.sessionId, args.workItemId);
    if (preview.restoration) return preview.restoration;
    if (preview.port !== undefined && preview.process) {
      this.touch(args.sessionId);
      return preview.port;
    }
    const failure = state.failures.get(args.workItemId);
    const isExplicitRetry =
      args.retryFailed === true && failure?.reason !== 'missing_static_entry';
    if (
      !failure ||
      !args.isSucceeded ||
      (failure.reason !== 'idle_timeout' && !isExplicitRetry)
    ) {
      return undefined;
    }
    state.failures.delete(args.workItemId);
    preview.autoRestarts = 0;
    this.deps.changed();
    const restoration = this.startVariantProcess({ ...args, preview });
    preview.restoration = restoration;
    try {
      return await restoration;
    } finally {
      if (preview.restoration === restoration) preview.restoration = undefined;
    }
  }

  async stopVariantServers(sessionId: string): Promise<number> {
    const state = this.sessions.get(sessionId);
    if (!state) return 0;
    this.clearIdleTimer(state);
    const stops: Array<Promise<void>> = [];
    for (const [workItemId, preview] of state.variants) {
      if (preview.pendingRestart) {
        clearTimeout(preview.pendingRestart);
        preview.pendingRestart = undefined;
      }
      if (!preview.process) continue;
      const process = preview.process;
      stops.push(
        this.deps.worktreeManager.stopDevServer(process).catch((error) => {
          log.warn(
            `stopDevServer failed for ${sessionId}/${workItemId}`,
            error,
          );
        }),
      );
      preview.process = undefined;
      preview.port = undefined;
    }
    await Promise.all(stops);
    return stops.length;
  }

  async closeSession(sessionId: string): Promise<void> {
    const state = this.sessions.get(sessionId);
    if (!state) return;
    await this.stopVariantServers(sessionId);
    for (const preview of state.variants.values()) {
      this.environment.forget(preview.worktreePath);
    }
    this.sessions.delete(sessionId);
  }

  async resolveCommand(
    sessionId: string,
    worktreePath: string,
    port: number,
    isFresh: boolean,
  ): Promise<ResolvedDevServer> {
    if (isFresh) {
      return {
        cwd: worktreePath,
        cmd: 'npm',
        args: [
          'run',
          'dev',
          '--',
          '--port',
          String(port),
          '--host',
          FRESH_DEV_SERVER_HOST,
        ],
        env: { PORT: String(port) },
        packageManager: 'npm',
      };
    }
    const environment = await this.deps.resolveProjectEnvironment(sessionId);
    if (environment.framework === 'static') {
      throw new Error('Static projects do not have a dev server command');
    }
    const cwd = await this.resolveExistingProjectCwd(
      sessionId,
      worktreePath,
      environment,
    );
    if (environment.devCommand) {
      assertDevScriptExists(cwd, environment.devCommand);
    }
    const detected = fs.existsSync(path.join(cwd, 'package.json'))
      ? await resolveProjectPackageManager({
          cwd,
          workspaceRoot: worktreePath,
        }).catch((error: unknown) => {
          throw new DevServerStartError({
            message: errorMessage(error),
            summary: errorMessage(error),
            detail: '',
            reason: 'dependency_install_failed',
            portInUse: false,
            reasonCode: failureReasonCode(error),
          });
        })
      : null;
    const packageManager =
      detected?.name ?? (environment.packageManager as PreviewPackageManager);
    if (packageManager !== environment.packageManager) {
      return {
        cwd,
        packageManager,
        ...buildDevServerCommand(
          environment.framework,
          packageManager,
          environment.devCommand,
          port,
        ),
      };
    }
    if (environment.buildDevCommand) {
      return {
        cwd,
        packageManager,
        ...environment.buildDevCommand(port),
      };
    }
    return {
      cwd,
      cmd: environment.packageManager,
      args: [environment.devCommand, '--port', String(port)],
      env: { PORT: String(port) },
      packageManager,
    };
  }

  private async startVariantProcess(args: {
    sessionId: string;
    workItemId: string;
    worktreePath: string;
    isFresh: boolean;
    preview: VariantPreview;
    restartTimer?: NodeJS.Timeout;
  }): Promise<number | undefined> {
    if (args.preview.port !== undefined && args.preview.process) {
      return args.preview.port;
    }
    if (!args.restartTimer && args.preview.pendingRestart) {
      clearTimeout(args.preview.pendingRestart);
      args.preview.pendingRestart = undefined;
    }
    const canContinue = (): boolean =>
      this.deps.isSessionLive(args.sessionId) &&
      !this.deps.isCleanupStarted(args.sessionId) &&
      (args.restartTimer === undefined ||
        args.preview.pendingRestart === args.restartTimer);
    const startedAt = Date.now();
    const projectContextKind = args.isFresh ? 'fresh' : 'existing';
    trackPreviewStarted(this.deps.telemetry, {
      sessionId: args.sessionId,
      variantId: args.workItemId,
      projectContextKind,
      previewKind: 'dev_server',
    });
    let scanFrom = await this.resolveStartPort(args.sessionId, args.isFresh);
    let installRetried = false;
    let lastCommand: ResolvedDevServer | undefined;
    for (let attempt = 1; attempt <= DEV_SERVER_START_MAX_ATTEMPTS; attempt++) {
      if (!canContinue()) return undefined;
      let port: number | undefined;
      try {
        port = await this.deps.worktreeManager.findFreePortFrom(scanFrom);
        const command = await this.resolveRunnableCommand(
          args.sessionId,
          args.worktreePath,
          port,
          args.isFresh,
        );
        lastCommand = command;
        if (!canContinue()) return undefined;
        const process = await this.deps.worktreeManager.startDevServer(
          command.cwd,
          port,
          command.cmd,
          command.args,
          command.env,
        );
        if (!canContinue()) {
          void this.deps.worktreeManager
            .stopDevServer(process)
            .catch(() => undefined);
          return undefined;
        }
        if (args.restartTimer) args.preview.pendingRestart = undefined;
        args.preview.port = port;
        args.preview.process = process;
        args.preview.command = command;
        this.watchVariantProcess(args, process);
        this.requireSession(args.sessionId).failures.delete(args.workItemId);
        this.deps.changed();
        trackFreshDevServerStarted(this.deps.telemetry, {
          sessionId: args.sessionId,
          variantId: args.workItemId,
          port,
        });
        trackPreviewReady(this.deps.telemetry, {
          sessionId: args.sessionId,
          variantId: args.workItemId,
          projectContextKind,
          previewKind: 'dev_server',
          hasPort: true,
          port,
          durationMs: Date.now() - startedAt,
        });
        this.touch(args.sessionId);
        return port;
      } catch (error) {
        if (!canContinue()) return undefined;
        const devError = isDevServerStartError(error) ? error : undefined;
        const portInUse = devError?.portInUse ?? false;
        const reason: DevServerFailureReason | 'unknown' =
          devError?.reason ?? 'unknown';
        const missingDepsOutput = isMissingDependencyOutput(
          devError?.detail ?? '',
        );
        const missingDeps =
          missingDepsOutput &&
          reason === 'exited' &&
          !installRetried &&
          lastCommand !== undefined &&
          canInstallWithoutTouchingHost(lastCommand.cwd);
        const willRetry =
          attempt < DEV_SERVER_START_MAX_ATTEMPTS &&
          (portInUse || missingDeps || (reason === 'exited' && attempt === 1));
        scanFrom = (port ?? scanFrom) + 1;
        if (willRetry) {
          if (missingDeps && lastCommand) {
            installRetried = true;
            try {
              await this.deps.installDependencies(lastCommand.cwd, {
                workspaceRoot: args.worktreePath,
                force: true,
                signal: this.deps.getDependencySignal(args.sessionId),
              });
            } catch (installError) {
              log.warn(
                `Dependency preparation failed for ${args.workItemId}`,
                installError,
              );
              this.failVariant(
                args,
                {
                  reason: 'dependency_install_failed',
                  portInUse: false,
                  detail: errorMessage(installError),
                },
                startedAt,
                installError,
                missingDepsOutput,
              );
              return undefined;
            }
          }
          continue;
        }
        this.failVariant(
          args,
          { reason, portInUse },
          startedAt,
          error,
          missingDepsOutput,
        );
        return undefined;
      } finally {
        if (port !== undefined) this.deps.worktreeManager.releasePort?.(port);
      }
    }
    return undefined;
  }

  private watchVariantProcess(
    args: {
      sessionId: string;
      workItemId: string;
      worktreePath: string;
      isFresh: boolean;
      preview: VariantPreview;
    },
    process: ChildProcess,
  ): void {
    process.once('exit', () => {
      if (args.preview.process !== process) return;
      args.preview.port = undefined;
      args.preview.process = undefined;
      const canRestart =
        args.preview.autoRestarts < DEV_SERVER_MAX_AUTO_RESTARTS &&
        this.deps.isSessionLive(args.sessionId) &&
        !this.deps.isCleanupStarted(args.sessionId);
      if (canRestart) {
        args.preview.autoRestarts += 1;
        this.deps.changed();
        const timer = setTimeout(() => {
          if (args.preview.pendingRestart !== timer) return;
          this.startVariantProcess({ ...args, restartTimer: timer })
            .catch((error) =>
              log.warn(`Auto-restart failed for ${args.workItemId}`, error),
            )
            .finally(() => {
              if (args.preview.pendingRestart === timer) {
                args.preview.pendingRestart = undefined;
              }
            });
        }, this.deps.devServerRestartDelayMs);
        args.preview.pendingRestart = timer;
        timer.unref?.();
        return;
      }
      this.sessions.get(args.sessionId)?.failures.set(args.workItemId, {
        reason: 'exited',
        portInUse: false,
      });
      this.deps.changed();
    });
  }

  private failVariant(
    args: { sessionId: string; workItemId: string; isFresh: boolean },
    failure: PreviewFailure,
    startedAt: number,
    error: unknown,
    missingDeps: boolean,
  ): void {
    const devError = isDevServerStartError(error) ? error : undefined;
    const detail =
      devError?.detail ||
      failure.detail ||
      (error === undefined ? '' : errorMessage(error));
    const reportedError = REPORTED_FAILURE_REASONS.has(failure.reason)
      ? error
      : undefined;
    this.requireSession(args.sessionId).failures.set(args.workItemId, {
      ...failure,
      ...(detail ? { detail } : {}),
      ...(reportedError === undefined ? {} : failureReason(reportedError)),
      nodeVersion: process.version,
    });
    let errorCode = 'DEV_SERVER_START_FAILED';
    if (failure.reason === 'dependency_install_failed') {
      errorCode = 'DEPENDENCY_INSTALL_FAILED';
    }
    if (failure.reason === 'missing_dev_script')
      errorCode = 'DEV_SCRIPT_MISSING';
    trackFreshDevServerFailed(this.deps.telemetry, {
      sessionId: args.sessionId,
      variantId: args.workItemId,
      errorCode,
      reason: failure.reason,
      portInUse: failure.portInUse,
      exitCode: devError?.exitCode,
      signal: devError?.signal,
      missingDeps,
      error: reportedError,
    });
    trackPreviewFailed(this.deps.telemetry, {
      sessionId: args.sessionId,
      variantId: args.workItemId,
      projectContextKind: args.isFresh ? 'fresh' : 'existing',
      previewKind: 'dev_server',
      errorCode,
      reason: failure.reason,
      portInUse: failure.portInUse,
      durationMs: Date.now() - startedAt,
      exitCode: devError?.exitCode,
      signal: devError?.signal,
      missingDeps,
      error: reportedError,
    });
    this.deps.changed();
  }

  private async stopIdleVariants(sessionId: string): Promise<void> {
    const state = this.sessions.get(sessionId);
    if (!state || this.deps.isCleanupStarted(sessionId)) return;
    if (this.deps.hasUiClients()) {
      this.touch(sessionId);
      return;
    }
    if (state.idleStop) return state.idleStop;
    const stop = (async () => {
      const expiring = [...state.variants.entries()].filter(
        ([, preview]) => preview.process || preview.pendingRestart,
      );
      await this.stopVariantServers(sessionId);
      for (const [workItemId] of expiring) {
        state.failures.set(workItemId, {
          reason: 'idle_timeout',
          portInUse: false,
        });
      }
      if (expiring.length > 0) {
        this.notifyPreviewPort(null);
        this.deps.changed();
      }
    })().finally(() => {
      if (state.idleStop === stop) state.idleStop = undefined;
    });
    state.idleStop = stop;
    await stop;
  }

  private async resolveRunnableCommand(
    sessionId: string,
    worktreePath: string,
    port: number,
    isFresh: boolean,
  ): Promise<ResolvedDevServer> {
    const command = await this.resolveCommand(
      sessionId,
      worktreePath,
      port,
      isFresh,
    );
    if (!isFresh) {
      const context = this.deps.getProjectContext(sessionId);
      const environment = await this.deps.resolveProjectEnvironment(sessionId);
      await this.environment.prepare({
        projectPath:
          context.kind === 'existing' && context.projectPath
            ? context.projectPath
            : environment.projectPath,
        worktreePath,
        cwd: path.relative(worktreePath, command.cwd) || '.',
      });
    }
    if (fs.existsSync(path.join(command.cwd, 'package.json'))) {
      await this.deps.installDependencies(command.cwd, {
        workspaceRoot: worktreePath,
        signal: this.deps.getDependencySignal(sessionId),
      });
    }
    return command;
  }

  private async resolveStartPort(
    sessionId: string,
    isFresh: boolean,
  ): Promise<number> {
    if (isFresh) return FRESH_DEV_SERVER_DEFAULT_PORT;
    try {
      const environment = await this.deps.resolveProjectEnvironment(sessionId);
      return environment.framework === 'static'
        ? 3000
        : (environment.defaultPort ?? 3000);
    } catch {
      return 3000;
    }
  }

  private async resolveExistingProjectCwd(
    sessionId: string,
    worktreePath: string,
    environment: ProjectEnvironment,
  ): Promise<string> {
    const fallback =
      await this.deps.worktreeManager.getProjectCwdInWorktree(worktreePath);
    const projectContext = this.deps.getProjectContext(sessionId);
    if (projectContext.kind !== 'existing' || !projectContext.projectPath) {
      return fallback;
    }
    if (
      !isPathStrictlyInsideRoot(
        environment.projectPath,
        projectContext.projectPath,
      )
    ) {
      return fallback;
    }
    return path.join(
      worktreePath,
      path.relative(environment.projectPath, projectContext.projectPath),
    );
  }

  private notifyPreviewPort(port: number | null): void {
    try {
      this.deps.switchPreviewPort?.(port);
    } catch (error) {
      log.warn(`switchPreviewPort(${port}) failed`, error);
    }
  }

  private clearIdleTimer(state: SessionPreviewState): void {
    if (!state.idleTimer) return;
    clearTimeout(state.idleTimer);
    state.idleTimer = undefined;
  }

  private requireSession(sessionId: string): SessionPreviewState {
    const state = this.sessions.get(sessionId);
    if (!state) throw new Error(`Preview session ${sessionId} is not open`);
    return state;
  }

  private requireVariant(
    sessionId: string,
    workItemId: string,
  ): VariantPreview {
    const preview = this.requireSession(sessionId).variants.get(workItemId);
    if (!preview)
      throw new Error(`Preview ${sessionId}/${workItemId} is not registered`);
    return preview;
  }
}
